<script setup>
import { computed, ref, watch } from 'vue';
import { useStorefront } from '../services/storefront.js';
import { StoreCopy } from '../services/storeCopy.js';
import { StoreTextLayout } from '../services/storeNavigation.js';
import { sectionSpacing } from '../services/design.js';
import { useStorePlayback } from '../services/storePlayback.js';
import StoreActionLink from './StoreActionLink.vue';
import Icon from './Icon.vue';
const sf = useStorefront(), index = ref(0);
const copy=new StoreCopy(()=>sf.design.value);
const settings = computed(() => sf.design.value.shop);
const slides = computed(() => settings.value.heroVariant === 'carousel' && settings.value.heroSlides.length ? settings.value.heroSlides : [{ id: 'main', image: settings.value.heroImage, buttonTarget: 'catalog' }]);
const current = computed(() => slides.value[index.value] || slides.value[0]);
const title = computed(() => current.value.title || settings.value.heroTitle);
const subtitle = computed(() => current.value.subtitle || settings.value.heroSubtitle);
const button = computed(() => current.value.buttonText || settings.value.heroButton);
const overlayVariant = computed(() => ['cover', 'carousel'].includes(settings.value.heroVariant));
const isImage = computed(() => settings.value.heroVariant === 'image');
const visible = computed(() => settings.value.showHero && (!isImage.value || current.value.image || sf.isPreview.value));
const spacing = computed(() => ({ ...sectionSpacing({ paddingX: settings.value.heroPaddingX, paddingY: settings.value.heroPaddingY, fullWidth: settings.value.heroFullWidth }), '--hero-height': `${settings.value.heroHeight}px`, '--hero-mobile-height': `${settings.value.heroMobileHeight}px`, '--hero-overlay': Number(settings.value.heroOverlay) / 100, '--hero-text': settings.value.heroTextColor, '--hero-align': settings.value.heroAlign }));
const playback = useStorePlayback({ enabled: () => visible.value && settings.value.heroVariant === 'carousel' && settings.value.heroAutoplay && slides.value.length > 1, interval: () => settings.value.heroInterval, advance: () => { index.value = (index.value + 1) % slides.value.length; } });
function select(value) { playback.pause(); index.value = (value + slides.value.length) % slides.value.length; }
watch(() => settings.value.heroVariant, () => { index.value = 0; });
watch(() => slides.value.length, length => { if (index.value >= length) index.value = 0; });
</script>

<template>
  <section v-if="visible" class="store-section store-hero-shell" :style="spacing" :dir="StoreTextLayout.direction(settings.heroDirection)" :aria-roledescription="settings.heroVariant === 'carousel' ? 'carrusel' : undefined" :aria-label="settings.heroVariant === 'carousel' ? 'Novedades de la tienda' : undefined" @pointerenter="playback.pointerEnter" @pointerleave="playback.pointerLeave" @focusin="playback.focusIn" @focusout="playback.focusOut">
    <div class="store-hero-frame" :class="['hero-variant-' + settings.heroVariant, 'hero-align-' + settings.heroAlign, {'hero-has-image':current.image, 'hero-edge':settings.heroFullWidth && !settings.heroPaddingX}]">
      <div v-if="current.image" :key="current.id + current.image" class="store-hero-visual" :class="{'hero-visual-overlay':overlayVariant}"><img :src="current.image" :alt="isImage ? (title || sf.store.value.name) : ''" fetchpriority="high"/></div>
      <div v-else class="store-hero-placeholder" :class="{'hero-visual-overlay':overlayVariant}" aria-hidden="true"><span></span><span></span><Icon name="package" :size="70"/></div>
      <div v-if="!isImage" class="store-hero-content" :aria-live="playback.playing.value ? 'off' : 'polite'">
        <template v-if="settings.heroShowText"><span v-if="copy.text('heroEyebrow',{storeName:sf.store.value.name})" class="hero-brand-label">{{copy.text('heroEyebrow',{storeName:sf.store.value.name})}}</span><h1 v-if="title">{{title}}</h1><p v-if="subtitle">{{subtitle}}</p></template>
        <StoreActionLink v-if="settings.heroShowButton" :target="current.buttonTarget || 'catalog'" :label="button" class="hero-action">{{button}}<Icon name="arrow-right" :size="17"/></StoreActionLink>
      </div>
      <div v-else-if="!current.image && sf.isPreview.value" class="hero-image-notice"><Icon name="image" :size="30"/><p>Agregá una imagen de portada para esta variante.</p></div>
      <div v-if="settings.heroVariant === 'carousel' && slides.length > 1" class="store-hero-controls">
        <button type="button" class="hero-control" aria-label="Imagen anterior" @click="select(index - 1)"><Icon name="arrow-left" :size="17"/></button>
        <div class="hero-pagination" aria-label="Elegir imagen"><button v-for="(slide,slideIndex) in slides" :key="slide.id" type="button" :aria-label="`Ver imagen ${slideIndex + 1}`" :aria-current="index === slideIndex ? 'true' : undefined" :class="{selected:index === slideIndex}" @click="select(slideIndex)"></button></div>
        <button type="button" class="hero-control" aria-label="Imagen siguiente" @click="select(index + 1)"><Icon name="arrow-right" :size="17"/></button>
        <button v-if="settings.heroAutoplay" type="button" class="hero-control hero-playback" :disabled="playback.reducedMotion.value" :aria-pressed="playback.manuallyPaused.value" :aria-label="playback.reducedMotion.value ? 'Reproducción automática desactivada por movimiento reducido' : playback.manuallyPaused.value ? 'Reanudar carrusel' : 'Pausar carrusel'" :title="playback.reducedMotion.value ? 'Tu dispositivo solicita reducir el movimiento' : playback.manuallyPaused.value ? 'Reanudar' : 'Pausar'" @click="playback.toggle"><svg width="15" height="15" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path v-if="playback.manuallyPaused.value" d="M6 3v14l11-7Z"/><path v-else d="M5 3h3v14H5zm7 0h3v14h-3z"/></svg></button>
      </div>
    </div>
  </section>
</template>

